// ---------------------------------------------------------------------------
// API helpers
// ---------------------------------------------------------------------------

/**
 * Creates a new Hyperswitch merchant account.
 * The response includes publishable_key but NOT the secret API key.
 * Use createApiKey() after this to obtain the merchant's secret key.
 *
 * @param {string} adminApiKey
 * @param {string} apiBaseUrl
 * @returns {Promise<{ merchantId: string, publishableKey: string }>}
 */
async function createMerchant(adminApiKey, apiBaseUrl) {
  const merchantId = `test_merchant_${Date.now()}`;
  const maxRetries = 3;
  const retryDelayMs = 5000;

  for (let attempt = 1; attempt <= maxRetries; attempt++) {
    const response = await fetch(`${apiBaseUrl}/accounts`, {
      method: "POST",
      headers: {
        "Content-Type": "application/json",
        "api-key": adminApiKey,
      },
      body: JSON.stringify({
        merchant_id:
          attempt > 1 ? `test_merchant_${Date.now()}_${attempt}` : merchantId,
        merchant_name: merchantId,
        locker_id: "m0010",
        merchant_details: {
          primary_contact_person: "Test User",
          primary_email: "test@hyperswitch.io",
        },
        primary_business_details: [
          {
            country: "US",
            business: "default",
          },
        ],
      }),
    });

    if (response.ok) {
      const data = await response.json();
      return {
        merchantId: data.merchant_id,
        publishableKey: data.publishable_key,
      };
    }

    const errorText = await response.text();
    if (attempt < maxRetries && response.status >= 500) {
      console.log(
        `[setup] Merchant creation attempt ${attempt}/${maxRetries} failed (HTTP ${response.status}), retrying in ${retryDelayMs / 1000}s...`,
      );
      await new Promise((resolve) => setTimeout(resolve, retryDelayMs));
      continue;
    }

    throw new Error(
      `[setup] Failed to create merchant: HTTP ${response.status} ${response.statusText}\n${errorText}`,
    );
  }
}

/**
 * Creates an API key for the merchant account.
 * The merchant creation response does NOT include the secret key —
 * it must be created separately via POST /api_keys/:merchant_id.
 *
 * @param {string} adminApiKey
 * @param {string} merchantId
 * @param {string} apiBaseUrl
 * @returns {Promise<string>} The plaintext API key (secret key).
 */
async function createApiKey(adminApiKey, merchantId, apiBaseUrl) {
  const response = await fetch(`${apiBaseUrl}/api_keys/${merchantId}`, {
    method: "POST",
    headers: {
      "Content-Type": "application/json",
      "api-key": adminApiKey,
    },
    body: JSON.stringify({
      name: `cypress_key_${Date.now()}`,
      description: "API key for cypress test run",
      expiration: "2027-12-31T23:59:59Z",
    }),
  });

  if (!response.ok) {
    const errorText = await response.text();
    throw new Error(
      `[setup] Failed to create API key: HTTP ${response.status} ${response.statusText}\n${errorText}`,
    );
  }

  const data = await response.json();
  return data.api_key;
}

/**
 * Creates a dedicated business profile for one connector.
 * @param {string} secretKey
 * @param {string} merchantId
 * @param {string} apiBaseUrl
 * @param {string} connectorName  Used only to generate a meaningful profile name.
 * @returns {Promise<string>}     The new profile_id.
 */
async function createBusinessProfile(
  secretKey,
  merchantId,
  apiBaseUrl,
  connectorName,
) {
  // Append a timestamp to ensure the label is unique across parallel runs.
  const profileName = `${connectorName}_profile_${Date.now()}`;

  const response = await fetch(
    `${apiBaseUrl}/account/${merchantId}/business_profile`,
    {
      method: "POST",
      headers: {
        "Content-Type": "application/json",
        "api-key": secretKey,
      },
      body: JSON.stringify({
        profile_name: profileName,
        return_url: "http://localhost:9060/completion",
      }),
    },
  );

  if (!response.ok) {
    const errorText = await response.text();
    throw new Error(
      `[setup] Failed to create business profile for "${connectorName}": HTTP ${response.status} ${response.statusText}\n${errorText}`,
    );
  }

  const data = await response.json();
  return data.profile_id;
}

/**
 * Patches a business profile to set authentication_connector_details.
 * Required for profiles that have both a payment processor (e.g. cybersource)
 * and an authentication processor (e.g. netcetera).
 *
 * @param {string} secretKey
 * @param {string} merchantId
 * @param {string} profileId
 * @param {string} authConnectorName  e.g. "netcetera"
 * @param {string} apiBaseUrl
 */
async function patchProfileAuthConnector(
  secretKey,
  merchantId,
  profileId,
  authConnectorName,
  apiBaseUrl,
) {
  const response = await fetch(
    `${apiBaseUrl}/account/${merchantId}/business_profile/${profileId}`,
    {
      method: "POST",
      headers: {
        "Content-Type": "application/json",
        "api-key": secretKey,
      },
      body: JSON.stringify({
        authentication_connector_details: {
          authentication_connectors: [authConnectorName],
          three_ds_requestor_url: "https://sandbox.hyperswitch.io",
        },
      }),
    },
  );

  if (!response.ok) {
    const errorText = await response.text();
    throw new Error(
      `[setup] Failed to patch auth connector on profile "${profileId}": HTTP ${response.status} ${response.statusText}\n${errorText}`,
    );
  }
}

/**
 * Creates a merchant connector account (MCA) on the given profile.
 * @param {string} secretKey
 * @param {string} merchantId
 * @param {string} profileId
 * @param {string} connectorName
 * @param {Record<string, string>} connectorAccountDetails  From creds.json.
 * @param {Record<string, any> | undefined} metadata        From creds.json.
 * @param {string} apiBaseUrl
 */
async function createMerchantConnectorAccount(
  secretKey,
  merchantId,
  profileId,
  connectorName,
  connectorAccountDetails,
  metadata,
  apiBaseUrl,
) {
  const paymentMethodsEnabled =
    CONNECTOR_PAYMENT_METHODS[connectorName] ||
    CONNECTOR_PAYMENT_METHODS.default;
  const connectorType =
    CONNECTOR_TYPE_MAP[connectorName] || "payment_processor";

  const requestBody = {
    connector_type: connectorType,
    connector_name: connectorName,
    connector_label: `${connectorName}_${Date.now()}`,
    profile_id: profileId,
    connector_account_details: connectorAccountDetails,
    payment_methods_enabled: paymentMethodsEnabled,
    test_mode: true,
    disabled: false,
  };

  // Pass metadata from creds.json if present (e.g. cybersource needs
  // google_pay, apple_pay_combined, acquirer_bin, acquirer_merchant_id).
  // Some connectors (e.g. klarna) require the metadata field to be present
  // even when empty, so we default to {}.
  requestBody.metadata = metadata || {};

  const response = await fetch(
    `${apiBaseUrl}/account/${merchantId}/connectors`,
    {
      method: "POST",
      headers: {
        "Content-Type": "application/json",
        "api-key": secretKey,
      },
      body: JSON.stringify(requestBody),
    },
  );

  if (!response.ok) {
    const errorText = await response.text();
    throw new Error(
      `[setup] Failed to create MCA for "${connectorName}": HTTP ${response.status} ${response.statusText}\n${errorText}`,
    );
  }
}

// ---------------------------------------------------------------------------
// creds.json parser
// ---------------------------------------------------------------------------

/**
 * Extracts connector_account_details from a creds.json entry.
 * Handles both direct and nested (connector_1 / connector_2) formats.
 *
 * Direct:   { "connector_account_details": { ... } }
 * Nested:   { "connector_1": { "connector_account_details": { ... } } }
 *
 * @param {Record<string, any>} connectorCreds
 * @returns {Record<string, string> | null}
 */
function extractConnectorAccountDetails(connectorCreds) {
  if (connectorCreds.connector_account_details) {
    return connectorCreds.connector_account_details;
  }
  if (
    connectorCreds.connector_1 &&
    connectorCreds.connector_1.connector_account_details
  ) {
    return connectorCreds.connector_1.connector_account_details;
  }
  return null;
}

/**
 * Extracts metadata from a creds.json entry.
 * Handles both direct and nested (connector_1 / connector_2) formats.
 *
 * @param {Record<string, any>} connectorCreds
 * @returns {Record<string, any> | undefined}
 */
function extractMetadata(connectorCreds) {
  if (connectorCreds.metadata) {
    return connectorCreds.metadata;
  }
  if (connectorCreds.connector_1 && connectorCreds.connector_1.metadata) {
    return connectorCreds.connector_1.metadata;
  }
  return undefined;
}

// ---------------------------------------------------------------------------
// Main orchestrator
// ---------------------------------------------------------------------------

/**
 * Creates a fresh merchant + per-connector business profiles + MCAs.
 * Called via cy.task("setupCredentials") — runs in the Node.js process.
 *
 * @param {{ adminApiKey: string, apiBaseUrl: string, credsFilePath: string }} params
 * @returns {Promise<{
 *   publishableKey: string,
 *   secretKey: string,
 *   merchantId: string,
 *   connectorProfileIds: Record<string, string>
 * }>}
 */
async function setupAllCredentials({ adminApiKey, apiBaseUrl, credsFilePath }) {
  // ── Cache check ───────────────────────────────────────────────────────────
  // The Node.js module stays loaded for the entire Cypress run, so this cache
  // is shared across all spec files.  Only the first spec triggers real API
  // calls; every subsequent spec gets an instant cache hit.
  if (_credentialsCache) {
    console.log(
      "[setup] Returning cached credentials (merchant already created for this run).",
    );
    return _credentialsCache;
  }

  // ── 1. Read and parse creds.json ─────────────────────────────────────────
  const absoluteCredsPath = path.isAbsolute(credsFilePath)
    ? credsFilePath
    : path.resolve(process.cwd(), credsFilePath);

  if (!fs.existsSync(absoluteCredsPath)) {
    throw new Error(
      `[setup] creds.json not found at: ${absoluteCredsPath}\n` +
        `Set CONNECTOR_AUTH_FILE_PATH (or CYPRESS_CONNECTOR_AUTH_FILE_PATH) ` +
        `to the path of your creds.json file.`,
    );
  }

  const credsJson = JSON.parse(fs.readFileSync(absoluteCredsPath, "utf-8"));
  console.log(
    `[setup] Loaded creds.json with connectors: ${Object.keys(credsJson)
      .filter((k) => k !== "Configs")
      .join(", ")}`,
  );

  // ── 2. Create merchant ───────────────────────────────────────────────────
  console.log(`[setup] Creating merchant on ${apiBaseUrl} ...`);
  const { merchantId, publishableKey } = await createMerchant(
    adminApiKey,
    apiBaseUrl,
  );
  console.log(`[setup] Merchant created → merchant_id: ${merchantId}`);

  // ── 2b. Create API key for the merchant ─────────────────────────────────
  // The merchant creation response does not include the secret key.
  // It must be created separately via POST /api_keys/:merchant_id.
  const secretKey = await createApiKey(adminApiKey, merchantId, apiBaseUrl);
  console.log(`[setup] API key created for merchant`);

  // ── 3. For each connector: create profile + MCA ──────────────────────────
  const connectorProfileIds = {};

  for (const [connectorName, connectorCreds] of Object.entries(credsJson)) {
    // Skip top-level "Configs" key (dynamic config metadata, not a connector)
    if (connectorName === "Configs" || typeof connectorCreds !== "object") {
      continue;
    }

    // Skip connectors not used by any Cypress web test to avoid
    // provisioning unnecessary business profiles and MCAs.
    if (!REQUIRED_CONNECTORS.includes(connectorName)) {
      console.log(
        `[setup] Skipping "${connectorName}" — not required by Cypress web tests.`,
      );
      continue;
    }

    const accountDetails = extractConnectorAccountDetails(connectorCreds);
    if (!accountDetails) {
      console.warn(
        `[setup] Skipping "${connectorName}": no connector_account_details found.`,
      );
      continue;
    }

    const metadata = extractMetadata(connectorCreds);

    try {
      // Determine the profile key — most connectors use their own name,
      // but sub-connectors like loonie/gigadat share a profile keyed as "interac".
      const profileKey = PROFILE_KEY_MAP[connectorName] || connectorName;

      // a) Create a new business profile, or reuse an existing one if a
      //    sub-connector already created it (e.g. gigadat reuses loonie's profile).
      let profileId = connectorProfileIds[profileKey];
      if (!profileId) {
        profileId = await createBusinessProfile(
          secretKey,
          merchantId,
          apiBaseUrl,
          connectorName,
        );
      }

      // b) MCA on that profile
      await createMerchantConnectorAccount(
        secretKey,
        merchantId,
        profileId,
        connectorName,
        accountDetails,
        metadata,
        apiBaseUrl,
      );

      connectorProfileIds[profileKey] = profileId;
      // Also expose netcetera under its own key so tests can look it up
      // via connectorEnum.NETCETERA ("netcetera") directly.
      if (profileKey !== connectorName) {
        connectorProfileIds[connectorName] = profileId;
      }
      console.log(
        `[setup] ${connectorName.padEnd(20)} → profile_id: ${profileId}` +
          (profileKey !== connectorName ? ` (shared as "${profileKey}")` : ""),
      );
    } catch (err) {
      // Log the error but continue with remaining connectors.
      // Individual tests for the failed connector will fail at runtime
      // when they can't find a profile_id — which is the desired behavior.
      console.error(
        `[setup] Error setting up "${connectorName}":`,
        err.message,
      );
    }
  }

  console.log(
    `[setup] Done. ${Object.keys(connectorProfileIds).length} connector(s) configured.`,
  );

  // ── Patch authentication_connector_details on profiles that need it ───────
  // Must run AFTER all MCAs are created so the auth connector MCA exists.
  for (const [profileKey, authConnector] of Object.entries(AUTH_CONNECTOR_FOR_PROFILE)) {
    const profileId = connectorProfileIds[profileKey];
    if (!profileId) {
      console.warn(`[setup] Skipping auth connector patch for "${profileKey}": profile not found.`);
      continue;
    }
    try {
      await patchProfileAuthConnector(secretKey, merchantId, profileId, authConnector, apiBaseUrl);
      console.log(`[setup] Patched profile ${profileId} with authentication_connector: ${authConnector}`);
    } catch (err) {
      const msg = err instanceof Error ? err.message : String(err);
      console.error(`[setup] Error patching auth connector for "${profileKey}":`, msg);
    }
  }

  _credentialsCache = {
    publishableKey,
    secretKey,
    merchantId,
    connectorProfileIds,
  };

  const cachePath = process.env.CREDENTIALS_OUTPUT_PATH
    ? path.resolve(process.env.CREDENTIALS_OUTPUT_PATH)
    : path.join(
        __dirname,
        `test-credentials-${process.env.TEST_ENV || "sandbox"}.json`,
      );
  try {
    fs.writeFileSync(cachePath, JSON.stringify(_credentialsCache, null, 2));
    console.log(
      `[setup] Credentials cached to ${cachePath} for reuse by subsequent runs.`,
    );
  } catch (err) {
    console.warn(`[setup] Could not cache credentials: ${err.message}`);
  }

  return _credentialsCache;
}

module.exports = { setupAllCredentials };

// ---------------------------------------------------------------------------
// Standalone CLI entry point — used by the CI "setup" job.
//
//   node setup.js
//
// Reads env vars:
//   ADMIN_API_KEY             — Hyperswitch admin key
//   HYPERSWITCH_API_URL       — target API base URL (sandbox / integ / local)
//   CONNECTOR_AUTH_FILE_PATH  — path to creds.json
//   CREDENTIALS_OUTPUT_PATH   — where to write test-credentials.json
//
// Writes a JSON file with:
//   { publishableKey, secretKey, merchantId, connectorProfileIds }
//
// The parallel Cypress jobs download this file and skip the setup task.
// ---------------------------------------------------------------------------
if (require.main === module) {
  (async () => {
    const adminApiKey = process.env.ADMIN_API_KEY;
    const apiBaseUrl = process.env.HYPERSWITCH_API_URL;
    const credsFilePath = process.env.CONNECTOR_AUTH_FILE_PATH;
    const outputPath =
      process.env.CREDENTIALS_OUTPUT_PATH || "./test-credentials.json";

    if (!adminApiKey) {
      console.error("[setup] Missing ADMIN_API_KEY env var.");
      process.exit(1);
    }
    if (!apiBaseUrl) {
      console.error("[setup] Missing HYPERSWITCH_API_URL env var.");
      process.exit(1);
    }
    if (!credsFilePath) {
      console.error("[setup] Missing CONNECTOR_AUTH_FILE_PATH env var.");
      process.exit(1);
    }

    try {
      const creds = await setupAllCredentials({
        adminApiKey,
        apiBaseUrl,
        credsFilePath,
      });
      fs.writeFileSync(outputPath, JSON.stringify(creds, null, 2));
      console.log(`[setup] Credentials written to ${outputPath}`);
    } catch (err) {
      console.error("[setup] Fatal error:", err.message);
      process.exit(1);
    }
  })();
}

/**
 * Layout: Grid Tabs Tests
 * Tests for tabs layout with paymentMethodsArrangementForTabs: "grid".
 * Tabs should be arranged in a CSS grid instead of a horizontal flex row.
 */
import * as testIds from "../../../../src/Utilities/TestUtils.bs";
import {
  getClientURL,
  createPaymentBody,
  changeObjectKeyValue,
  connectorEnum,
  connectorProfileIdMapping,
  defaultBillingAddress,
} from "../../support/utils";
import { stripeCards } from "../../support/cards";

describe("Layout - Grid Tabs", () => {
  let publishableKey: string;
  let secretKey: string;
  let getIframeBody: () => Cypress.Chainable<JQuery<HTMLBodyElement>>;
  const iframeSelector =
    "#orca-payment-element-iframeRef-orca-elements-payment-element-payment-element";

  const gridTabsLayout = {
    type: "tabs",
    paymentMethodsArrangementForTabs: "grid",
  };

  beforeEach(() => {
    publishableKey = Cypress.env("HYPERSWITCH_PUBLISHABLE_KEY");
    secretKey = Cypress.env("HYPERSWITCH_SECRET_KEY");
    getIframeBody = () => cy.paymentElementBody();
    changeObjectKeyValue(
      createPaymentBody,
      "customer_id",
      "layout_grid_tabs_test_user",
    );
    changeObjectKeyValue(
      createPaymentBody,
      "authentication_type",
      "no_three_ds",
    );
    changeObjectKeyValue(createPaymentBody, "capture_method", "automatic");
    changeObjectKeyValue(
      createPaymentBody,
      "profile_id",
      connectorProfileIdMapping.get(connectorEnum.STRIPE),
    );
    changeObjectKeyValue(createPaymentBody, "billing", defaultBillingAddress);

    cy.createPaymentIntent(secretKey, createPaymentBody).then(() => {
      cy.getGlobalState("clientSecret").then((clientSecret) => {
        cy.visit(
          getClientURL(
            clientSecret,
            publishableKey,
            undefined,
            undefined,
            gridTabsLayout,
          ),
        );
        cy.waitForSDKReady();
      });
    });
  });

  describe("Grid Tabs Container", () => {
    it("should render tabs layout (not accordion)", () => {
      getIframeBody()
        .find(".TabHeader")
        .should("be.visible");

      getIframeBody().find(".AccordionContainer").should("not.exist");
    });

    it("should use CSS grid display on the tab header", () => {
      getIframeBody()
        .find(".TabHeader")
        .should("have.css", "display", "grid");
    });

    it("should have grid-template-columns set for grid arrangement", () => {
      getIframeBody()
        .find(".TabHeader")
        .then(($el) => {
          const gridCols = $el.css("grid-template-columns");
          expect(gridCols).to.not.be.empty;
          expect(gridCols).to.not.equal("none");
        });
    });

    it("should have gap between grid items", () => {
      getIframeBody()
        .find(".TabHeader")
        .then(($el) => {
          const gap = $el.css("gap");
          expect(gap).to.not.equal("normal");
        });
    });
  });

  describe("Grid Tabs Items", () => {
    it("should render tab buttons with Tab CSS class", () => {
      getIframeBody().find(".Tab").should("have.length.at.least", 1);
    });

    it("should display all payment methods without overflow dropdown", () => {
      getIframeBody()
        .find(`[data-testid=${testIds.paymentMethodDropDownTestId}]`)
        .should("not.exist");
    });

    it("should have one selected tab by default", () => {
      getIframeBody()
        .find(".Tab--selected")
        .should("have.length", 1);
    });

    it("should switch selection when clicking a different grid tab", () => {
      getIframeBody().find(".Tab").then(($tabs) => {
        if ($tabs.length > 1) {
          cy.wrap($tabs.eq(1)).safeClick();

          getIframeBody()
            .find(".Tab")
            .eq(1)
            .should("have.class", "Tab--selected");
        }
      });
    });
  });

  describe("Payment Flow with Grid Tabs", () => {
    it("should show card input fields when card tab is selected", () => {
      getIframeBody()
        .find(`[data-testid=${testIds.cardNoInputTestId}]`)
        .should("be.visible");
    });

    it("should complete payment successfully with grid tabs layout", () => {
      const { cardNo, card_exp_month, card_exp_year, cvc } =
        stripeCards.successCard;

      cy.enterCardDetails({ cardNo, card_exp_month, card_exp_year, cvc });

      cy.get("#submit").should("be.visible").click();

      cy.contains("Thanks for your order!", { timeout: 10000 }).should(
        "be.visible",
      );
    });
  });
});

import {
  getClientURL,
  createPaymentBody,
  changeObjectKeyValue,
} from "../../support/utils";

describe("SDK Initialization Tests", () => {
  let publishableKey: string;
  let secretKey: string;

  beforeEach(() => {
    publishableKey = Cypress.env("HYPERSWITCH_PUBLISHABLE_KEY");
    secretKey = Cypress.env("HYPERSWITCH_SECRET_KEY");
    changeObjectKeyValue(createPaymentBody, "customer_id", "sdk_init_test_user");
  });

  it("should initialize SDK with valid publishable key", () => {
    cy.createPaymentIntent(secretKey, createPaymentBody).then(() => {
      cy.getGlobalState("clientSecret").then((clientSecret) => {
        cy.visit(getClientURL(clientSecret, publishableKey));
      });
    });

    cy.waitForSDKReady();
  });

  it("should fail initialization with invalid publishable key format", () => {
    const invalidKey = "invalid_key_format";

    cy.createPaymentIntent(secretKey, createPaymentBody).then(() => {
      cy.getGlobalState("clientSecret").then((clientSecret) => {
        // Install the console.error stub via onBeforeLoad so it is registered
        // BEFORE the SDK's JS runs — registering cy.on() after cy.visit() is
        // too late and the stub never captures init-time errors.
        cy.visit(getClientURL(clientSecret, invalidKey), {
          onBeforeLoad(win) {
            cy.stub(win.console, "error").as("consoleError");
          },
        });
      });
    });

    cy.get("@consoleError").should("have.been.called");
  });

  it("should initialize with custom backend URL", () => {
    const customBackendUrl =
      Cypress.env("HYPERSWITCH_CUSTOM_BACKEND_URL") ||
      Cypress.env("HYPERSWITCH_API_URL");

    cy.createPaymentIntent(secretKey, createPaymentBody).then(() => {
      cy.getGlobalState("clientSecret").then((clientSecret) => {
        const url = `${getClientURL(clientSecret, publishableKey)}&customBackendUrl=${encodeURIComponent(customBackendUrl)}`;
        cy.visit(url);
      });
    });

    cy.waitForSDKReady();
  });

  it("should reinitialize SDK when isForceInit is true", () => {
    cy.createPaymentIntent(secretKey, createPaymentBody).then(() => {
      cy.getGlobalState("clientSecret").then((clientSecret) => {
        const url = `${getClientURL(clientSecret, publishableKey)}&isForceInit=true`;
        cy.visit(url);
      });
    });

    cy.waitForSDKReady();

    cy.window().then((win: any) => {
      expect(win.Hyper).to.exist;
    });
  });

  it("should initialize SDK with profile ID", () => {
    cy.createPaymentIntent(secretKey, createPaymentBody).then(() => {
      cy.getGlobalState("clientSecret").then((clientSecret) => {
        cy.visit(getClientURL(clientSecret, publishableKey));
      });
    });

    cy.waitForSDKReady();
  });
});

/**
 * Layout: Spaced Accordion Tests
 * Tests for accordion layout with spacedAccordionItems: true.
 * Items should have spacing between them, individual border-radius,
 * and visible borders on each item.
 */
import * as testIds from "../../../../src/Utilities/TestUtils.bs";
import {
  getClientURL,
  createPaymentBody,
  changeObjectKeyValue,
  connectorEnum,
  connectorProfileIdMapping,
  defaultBillingAddress,
} from "../../support/utils";
import { stripeCards } from "../../support/cards";

describe("Layout - Spaced Accordion", () => {
  let publishableKey: string;
  let secretKey: string;
  let getIframeBody: () => Cypress.Chainable<JQuery<HTMLBodyElement>>;
  const iframeSelector =
    "#orca-payment-element-iframeRef-orca-elements-payment-element-payment-element";

  const spacedAccordionLayout = {
    type: "accordion",
    spacedAccordionItems: true,
  };

  beforeEach(() => {
    publishableKey = Cypress.env("HYPERSWITCH_PUBLISHABLE_KEY");
    secretKey = Cypress.env("HYPERSWITCH_SECRET_KEY");
    getIframeBody = () => cy.paymentElementBody();
    changeObjectKeyValue(
      createPaymentBody,
      "customer_id",
      "layout_spaced_accordion_test_user",
    );
    changeObjectKeyValue(
      createPaymentBody,
      "authentication_type",
      "no_three_ds",
    );
    changeObjectKeyValue(createPaymentBody, "capture_method", "automatic");
    changeObjectKeyValue(
      createPaymentBody,
      "profile_id",
      connectorProfileIdMapping.get(connectorEnum.STRIPE),
    );
    changeObjectKeyValue(createPaymentBody, "billing", defaultBillingAddress);

    cy.createPaymentIntent(secretKey, createPaymentBody).then(() => {
      cy.getGlobalState("clientSecret").then((clientSecret) => {
        cy.visit(
          getClientURL(
            clientSecret,
            publishableKey,
            undefined,
            undefined,
            spacedAccordionLayout,
          ),
        );
        cy.waitForSDKReady();
      });
    });
  });

  describe("Spaced Accordion Container", () => {
    it("should render accordion container (not tabs)", () => {
      getIframeBody()
        .find(".AccordionContainer")
        .should("be.visible");
    });

    it("should NOT render tab header", () => {
      getIframeBody().find(".TabHeader").should("not.exist");
    });

    it("should render multiple accordion items", () => {
      getIframeBody()
        .find(".AccordionItem")
        .should("have.length.at.least", 1);
    });
  });

  describe("Spaced Accordion Spacing", () => {
    it("should have margin-bottom between accordion items (spaced mode)", () => {
      getIframeBody()
        .find(".AccordionItem")
        .first()
        .then(($el) => {
          const marginBottom = parseFloat($el.css("margin-bottom"));
          expect(marginBottom).to.be.greaterThan(0);
        });
    });

    it("should have individual border-radius on each item (not shared edges)", () => {
      getIframeBody()
        .find(".AccordionItem")
        .first()
        .then(($el) => {
          const borderRadius = $el.css("border-radius");
          expect(borderRadius).to.not.equal("0px");
        });
    });

    it("should have visible bottom border on each item", () => {
      getIframeBody()
        .find(".AccordionItem")
        .first()
        .then(($el) => {
          const borderBottomStyle = $el.css("border-bottom-style");
          expect(borderBottomStyle).to.equal("solid");
        });
    });
  });

  describe("Spaced Accordion Selection", () => {
    it("should have one item selected by default", () => {
      getIframeBody()
        .find(".AccordionItem--selected")
        .should("have.length", 1);
    });

    it("should switch selection when clicking a different item", () => {
      getIframeBody().find(".AccordionItem").then(($items) => {
        if ($items.length > 1) {
          cy.wrap($items.eq(1)).safeClick();

          getIframeBody()
            .find(".AccordionItem")
            .eq(1)
            .find(".AccordionItem--selected")
            .should("exist");
        }
      });
    });
  });

  describe("Payment Flow with Spaced Accordion", () => {
    it("should show card fields when card item is selected", () => {
      getIframeBody()
        .find(`[data-testid=${testIds.cardNoInputTestId}]`)
        .should("be.visible");
    });

    it("should complete payment successfully with spaced accordion layout", () => {
      const { cardNo, card_exp_month, card_exp_year, cvc } =
        stripeCards.successCard;

      cy.enterCardDetails({ cardNo, card_exp_month, card_exp_year, cvc });

      cy.get("#submit").should("be.visible").click();

      cy.contains("Thanks for your order!", { timeout: 10000 }).should(
        "be.visible",
      );
    });
  });
});

/**
 * Terms Display Tests
 * Verifies that the terms option controls the visibility of terms text
 * for different payment methods (Auto, Always, Never).
 * Note: Card terms only display for mandate/setup flows (NEW_MANDATE/SETUP_MANDATE).
