import {
  getClientURL,
  createPaymentBody,
  changeObjectKeyValue,
} from "../../support/utils";

describe("PaymentElement branding Option", () => {
  let publishableKey: string;
  let secretKey: string;
  let getIframeBody: () => Cypress.Chainable<JQuery<HTMLBodyElement>>;
  const iframeSelector =
    "#orca-payment-element-iframeRef-orca-elements-payment-element-payment-element";

  beforeEach(() => {
    publishableKey = Cypress.env("HYPERSWITCH_PUBLISHABLE_KEY");
    secretKey = Cypress.env("HYPERSWITCH_SECRET_KEY");
    getIframeBody = () => cy.iframe(iframeSelector);
    changeObjectKeyValue(
      createPaymentBody,
      "customer_id",
      "branding_test_user"
    );
    changeObjectKeyValue(
      createPaymentBody,
      "authentication_type",
      "no_three_ds"
    );
  });

  describe('branding: "auto" (default)', () => {
    beforeEach(() => {
      cy.createPaymentIntent(secretKey, createPaymentBody).then(() => {
        cy.getGlobalState("clientSecret").then((clientSecret) => {
          cy.visit(
            getClientURL(
              clientSecret,
              publishableKey,
              undefined,
              undefined,
              undefined,
              { branding: "auto" }
            )
          );
          cy.waitForSDKReady();
        });
      });
    });

    it("should display the Hyperswitch branding icon", () => {
      getIframeBody()
        .find("svg", { timeout: 10000 })
        .filter((_index, el) => {
          const useEl = el.querySelector("use");
          if (!useEl) return false;
          const href =
            useEl.getAttribute("href") ||
            useEl.getAttributeNS("http://www.w3.org/1999/xlink", "href") ||
            "";
          return href.includes("powerd-by-hyper");
        })
        .should("have.length.greaterThan", 0);
    });
  });

  describe('branding: "never"', () => {
    beforeEach(() => {
      cy.createPaymentIntent(secretKey, createPaymentBody).then(() => {
        cy.getGlobalState("clientSecret").then((clientSecret) => {
          cy.visit(
            getClientURL(
              clientSecret,
              publishableKey,
              undefined,
              undefined,
              undefined,
              { branding: "never" }
            )
          );
          cy.waitForSDKReady();
        });
      });
    });

    it("should hide the Hyperswitch branding icon", () => {
      getIframeBody().then(($body) => {
        const svgs = $body.find("svg");
        const brandingSvgs = svgs.filter((_index, el) => {
          const useEl = el.querySelector("use");
          if (!useEl) return false;
          const href =
            useEl.getAttribute("href") ||
            useEl.getAttributeNS("http://www.w3.org/1999/xlink", "href") ||
            "";
          return href.includes("powerd-by-hyper");
        });
        expect(brandingSvgs.length).to.equal(0);
      });
    });
  });
});

import {
  getClientURL,
  createPaymentBody,
  changeObjectKeyValue,
} from "../../support/utils";

describe("SDK Error Handling Tests", () => {
  let publishableKey: string;
  let secretKey: string;

  beforeEach(() => {
    publishableKey = Cypress.env("HYPERSWITCH_PUBLISHABLE_KEY");
    secretKey = Cypress.env("HYPERSWITCH_SECRET_KEY");
    changeObjectKeyValue(createPaymentBody, "customer_id", "error_handling_test_user");
  });

  it("should handle missing client secret error", () => {
    cy.visit(getClientURL("", publishableKey), {
      failOnStatusCode: false,
    });

    cy.get("#orca-payment-element-iframeRef-orca-elements-payment-element-payment-element", { timeout: 5000 })
      .should("not.exist");
  });

  it("should handle invalid client secret format", () => {
    const invalidClientSecret = "invalid_secret_format";

    cy.visit(getClientURL(invalidClientSecret, publishableKey), {
      failOnStatusCode: false,
    });

    cy.get("#orca-payment-element-iframeRef-orca-elements-payment-element-payment-element", { timeout: 5000 })
      .should("not.exist");
  });

  it("should handle network errors gracefully", () => {
    // cy.intercept works for browser-level requests (XHR/fetch), not cy.request.
    // Intercept the SDK's payment_methods call to simulate a network failure
    // and verify the page remains accessible without crashing.
    cy.intercept("GET", "**/account/payment_methods*", {
      forceNetworkError: true,
    }).as("paymentMethodsError");

    cy.createPaymentIntent(secretKey, createPaymentBody).then(() => {
      cy.getGlobalState("clientSecret").then((clientSecret) => {
        cy.visit(getClientURL(clientSecret, publishableKey), {
          failOnStatusCode: false,
        });
      });
    });

    // Page should remain accessible even when the payment methods request fails
    cy.get("body").should("exist");
    cy.get("#submit").should("exist");
  });

  it("should handle 401 unauthorized error", () => {
    const invalidSecretKey = "invalid_key";

    cy.request({
      method: "POST",
      url: `${Cypress.env("HYPERSWITCH_API_URL")}/payments`,
      headers: {
        "Content-Type": "application/json",
        "api-key": invalidSecretKey,
      },
      body: createPaymentBody,
      failOnStatusCode: false,
    }).then((response) => {
      expect([401, 404]).to.include(response.status);
    });
  });

  it("should handle 404 not found error", () => {
    cy.request({
      method: "GET",
      url: `${Cypress.env("HYPERSWITCH_API_URL")}/nonexistent_endpoint`,
      headers: {
        "Content-Type": "application/json",
        "api-key": secretKey,
      },
      failOnStatusCode: false,
    }).then((response) => {
      expect([200, 404]).to.include(response.status);
    });
  });

  it("should handle timeout errors", () => {
    // cy.intercept does not affect cy.request (which is a direct Node.js call).
    // Instead, test actual API error behaviour by retrieving a non-existent payment,
    // which the server must return a 4xx error for.
    cy.request({
      method: "GET",
      url: `${Cypress.env("HYPERSWITCH_API_URL")}/payments/pay_000000000000000000000000000000`,
      headers: {
        "Content-Type": "application/json",
        "api-key": secretKey,
      },
      failOnStatusCode: false,
    }).then((response) => {
      expect(response.status).to.satisfy((status: number) => status >= 400);
    });
  });

  it("should handle SDK script loading errors", () => {
    cy.intercept("GET", "**/app.js", {
      statusCode: 500,
      body: "Server Error",
    }).as("sdkScriptError");

    cy.on("window:before:load", (win) => {
      cy.stub(win.console, "error").as("consoleError");
    });

    cy.createPaymentIntent(secretKey, createPaymentBody).then(() => {
      cy.getGlobalState("clientSecret").then((clientSecret) => {
        cy.visit(getClientURL(clientSecret, publishableKey));
      });
    });

    cy.get("#orca-payment-element-iframeRef-orca-elements-payment-element-payment-element", { timeout: 5000 })
      .should("not.exist");
  });

  it("should recover from temporary network failures", () => {
    let requestCount = 0;

    cy.intercept("GET", "**/payment_methods*", (req) => {
      requestCount++;
      if (requestCount === 1) {
        req.reply({
          forceNetworkError: true,
        });
      } else {
        req.reply({
          statusCode: 200,
          body: { payment_methods: [] },
        });
      }
    }).as("paymentMethods");

    cy.createPaymentIntent(secretKey, createPaymentBody).then(() => {
      cy.getGlobalState("clientSecret").then((clientSecret) => {
        cy.visit(getClientURL(clientSecret, publishableKey));
      });
    });

    cy.get("#orca-payment-element-iframeRef-orca-elements-payment-element-payment-element", {
      timeout: 10000,
    }).should("be.visible");
  });

  it("should handle invalid publishable key prefix", () => {
    const invalidPrefixKey = "pk_invalid_test_key";

    cy.createPaymentIntent(secretKey, createPaymentBody).then(() => {
      cy.getGlobalState("clientSecret").then((clientSecret) => {
        cy.visit(getClientURL(clientSecret, invalidPrefixKey));
      });
    });

    cy.on("window:before:load", (win) => {
      cy.stub(win.console, "error").as("consoleError");
    });

    cy.get("@consoleError").should("have.been.called");
  });

  it("should handle missing required parameters", () => {
    cy.visit(`${getClientURL("", "")}`);

    cy.on("window:before:load", (win) => {
      cy.stub(win.console, "error").as("consoleError");
    });

    cy.get("@consoleError").should("have.been.called");
  });

  it("should log errors to Sentry when configured", () => {
    const sentryDsn = Cypress.env("SENTRY_DSN");

    if (sentryDsn) {
      cy.intercept("POST", "**sentry.io**", (req) => {
        expect(req.body).to.exist;
      }).as("sentryRequest");

      cy.createPaymentIntent(secretKey, createPaymentBody).then(() => {
        cy.getGlobalState("clientSecret").then((clientSecret) => {
          cy.visit(`${getClientURL(clientSecret, publishableKey)}&sentryDsn=${encodeURIComponent(sentryDsn)}`);
        });
      });

      cy.window().then((win: any) => {
        if (win.triggerTestError) {
          win.triggerTestError();
        }
      });

      cy.wait("@sentryRequest", { timeout: 5000 });
    }
  });
});

/**
 * Themes / Appearance Tests
 * Tests that each theme preset applies correct visual styling:
 * default, midnight, charcoal, soft, brutal, bubblegum.
 *
 * Key architectural notes:
 * - Each theme has unique styling approaches (some use background-color,
 *   some use CSS gradients, some only set color/box-shadow on selected tabs).
 * - Border-radius is consistently set by all themes on .Tab elements.
 * - The #submit button is on the HOST page and does NOT get theme styles.
 * - Theme rules are injected via <style id="themestyle"> in iframe body.
 * - We focus on reliably testable properties: border-radius, existence of
 *   theme stylesheet, and theme-specific visual differentiation.
 */
import * as testIds from "../../../../src/Utilities/TestUtils.bs";
import {
  getClientURL,
  createPaymentBody,
  changeObjectKeyValue,
  connectorEnum,
  connectorProfileIdMapping,
  defaultBillingAddress,
} from "../../support/utils";
import { stripeCards } from "../../support/cards";

/**
 * Theme preset expected border-radius values (from *Theme.res files).
 */
const themeBorderRadius: Record<string, string> = {
  default: "4px",
  midnight: "10px",
  charcoal: "10px",
  soft: "10px",
  brutal: "6px",
  bubblegum: "2px",
};

describe("Themes / Appearance", () => {
  let publishableKey: string;
  let secretKey: string;
  let getIframeBody: () => Cypress.Chainable<JQuery<HTMLBodyElement>>;
  const iframeSelector =
    "#orca-payment-element-iframeRef-orca-elements-payment-element-payment-element";

  const setupAndVisit = (theme?: string) => {
    changeObjectKeyValue(
      createPaymentBody,
      "customer_id",
      "theme_test_user",
    );
    changeObjectKeyValue(
      createPaymentBody,
      "authentication_type",
      "no_three_ds",
    );
    changeObjectKeyValue(createPaymentBody, "capture_method", "automatic");
    changeObjectKeyValue(
      createPaymentBody,
      "profile_id",
      connectorProfileIdMapping.get(connectorEnum.STRIPE),
    );
    changeObjectKeyValue(createPaymentBody, "currency", "USD");
    changeObjectKeyValue(createPaymentBody, "billing", defaultBillingAddress);

    cy.createPaymentIntent(secretKey, createPaymentBody).then(() => {
      cy.getGlobalState("clientSecret").then((clientSecret) => {
        cy.visit(
          getClientURL(clientSecret, publishableKey, undefined, theme),
        );
        cy.waitForSDKReady();
      });
    });
  };

  // TrustPay (EUR + NL) exposes card + bank_redirect, so the SDK renders
  // multiple payment-method tabs (Card selected by default). Used by the
  // non-selected-tab assertions, which need at least one non-selected tab to
  // exist — stripe/USD only ever surfaces a single "card" tab on integ.
  const setupMultiTabAndVisit = (theme?: string) => {
    changeObjectKeyValue(createPaymentBody, "customer_id", "theme_multitab_user");
    changeObjectKeyValue(createPaymentBody, "authentication_type", "no_three_ds");
    changeObjectKeyValue(createPaymentBody, "capture_method", "automatic");
    changeObjectKeyValue(
      createPaymentBody,
      "profile_id",
      connectorProfileIdMapping.get(connectorEnum.TRUSTPAY),
    );
    changeObjectKeyValue(createPaymentBody, "currency", "EUR");
    changeObjectKeyValue(createPaymentBody, "billing", {
      email: "theme_test@example.com",
      address: {
        ...defaultBillingAddress,
        city: "Amsterdam",
        state: "Noord-Holland",
        zip: "1011",
        country: "NL",
      },
    });

    cy.createPaymentIntent(secretKey, createPaymentBody).then(() => {
      cy.getGlobalState("clientSecret").then((clientSecret) => {
        cy.visit(getClientURL(clientSecret, publishableKey, undefined, theme));
        cy.waitForSDKReady();
      });
    });
  };

  beforeEach(() => {
    publishableKey = Cypress.env("HYPERSWITCH_PUBLISHABLE_KEY");
    secretKey = Cypress.env("HYPERSWITCH_SECRET_KEY");
    getIframeBody = () => cy.iframe(iframeSelector);
  });

  describe("Default Theme", () => {
    beforeEach(() => {
      setupAndVisit(); // No theme param = default
    });

    it("should render SDK with tabs in default theme", () => {
      getIframeBody().find(".Tab").should("have.length.at.least", 1);
    });

    it("should apply default border-radius (4px) to tab elements", () => {
      getIframeBody()
        .find(".Tab")
        .first()
        .should("have.css", "border-radius", themeBorderRadius.default);
    });

    it("should have a selected tab with primary-colored text", () => {
      getIframeBody()
        .find(".Tab--selected")
        .first()
        .should("have.css", "color", "rgb(0, 109, 249)");
    });

    it("should apply border to non-selected tab elements", () => {
      setupMultiTabAndVisit();
      getIframeBody()
        .find(".Tab")
        .not(".Tab--selected")
        .first()
        .then(($el) => {
          const borderStyle = $el.css("border-top-style");
          expect(borderStyle).to.equal("solid");
        });
    });

    it("should complete payment with default theme", () => {
      const { cardNo, card_exp_month, card_exp_year, cvc } =
        stripeCards.successCard;
      cy.enterCardDetails({ cardNo, card_exp_month, card_exp_year, cvc });
      cy.get("#submit").should("be.visible").click();
      cy.contains("Thanks for your order!", { timeout: 10000 }).should(
        "be.visible",
      );
    });
  });

  describe("Midnight Theme", () => {
    beforeEach(() => {
      setupAndVisit("midnight");
    });

    it("should apply midnight border-radius (10px) to tabs", () => {
      getIframeBody()
        .find(".Tab")
        .first()
        .should("have.css", "border-radius", themeBorderRadius.midnight);
    });

    it("should apply midnight dark background to non-selected tabs", () => {
      setupMultiTabAndVisit("midnight");
      getIframeBody()
        .find(".Tab")
        .not(".Tab--selected")
        .first()
        .should("have.css", "background-color", "rgb(48, 49, 61)");
    });

    it("should apply midnight primary color as selected tab background", () => {
      getIframeBody()
        .find(".Tab--selected")
        .first()
        .should("have.css", "background-color", "rgb(133, 217, 150)");
    });

    it("should visually differ from default theme (border-radius)", () => {
      getIframeBody()
        .find(".Tab")
        .first()
        .should("not.have.css", "border-radius", themeBorderRadius.default);
    });

    it("should complete payment with midnight theme", () => {
      const { cardNo, card_exp_month, card_exp_year, cvc } =
        stripeCards.successCard;
      cy.enterCardDetails({ cardNo, card_exp_month, card_exp_year, cvc });
      cy.get("#submit").should("be.visible").click();
      cy.contains("Thanks for your order!", { timeout: 10000 }).should(
        "be.visible",
      );
    });
  });

  describe("Charcoal Theme", () => {
    beforeEach(() => {
      setupAndVisit("charcoal");
    });

    it("should apply charcoal border-radius (10px)", () => {
      getIframeBody()
        .find(".Tab")
        .first()
        .should("have.css", "border-radius", themeBorderRadius.charcoal);
    });

    it("should apply charcoal light-gray background to non-selected tabs", () => {
      setupMultiTabAndVisit("charcoal");
      getIframeBody()
        .find(".Tab")
        .not(".Tab--selected")
        .first()
        .should("have.css", "background-color", "rgb(240, 243, 245)");
    });

    it("should apply charcoal primary (black) to selected tab background", () => {
      getIframeBody()
        .find(".Tab--selected")
        .first()
        .should("have.css", "background-color", "rgb(0, 0, 0)");
    });
  });

  describe("Soft Theme", () => {
    beforeEach(() => {
      setupAndVisit("soft");
    });

    it("should apply soft border-radius (10px)", () => {
      getIframeBody()
        .find(".Tab")
        .first()
        .should("have.css", "border-radius", themeBorderRadius.soft);
    });

    it("should apply soft styling distinct from default theme", () => {
      getIframeBody()
        .find(".Tab")
        .first()
        .should("not.have.css", "border-radius", "4px");
    });

    it("should apply soft primary color to selected tab text", () => {
      getIframeBody()
        .find(".Tab--selected")
        .first()
        .should("have.css", "color", "rgb(125, 143, 255)");
    });
  });

  describe("Brutal Theme", () => {
    beforeEach(() => {
      setupAndVisit("brutal");
    });

    it("should apply brutal border-radius (6px)", () => {
      getIframeBody()
        .find(".Tab")
        .first()
        .should("have.css", "border-radius", themeBorderRadius.brutal);
    });

    it("should apply brutal yellow background to selected tab", () => {
      getIframeBody()
        .find(".Tab--selected")
        .first()
        .should("have.css", "background-color", "rgb(245, 251, 31)");
    });

    it("should have distinct visual styling from default theme", () => {
      getIframeBody()
        .find(".Tab")
        .first()
        .should("not.have.css", "border-radius", themeBorderRadius.default);
    });
  });

  describe("Bubblegum Theme", () => {
    beforeEach(() => {
      setupAndVisit("bubblegum");
    });

    it("should apply bubblegum border-radius (2px)", () => {
      getIframeBody()
        .find(".Tab")
        .first()
        .should("have.css", "border-radius", themeBorderRadius.bubblegum);
    });

    it("should apply bubblegum pink background to selected tab", () => {
      getIframeBody()
        .find(".Tab--selected")
        .first()
        .should("have.css", "background-color", "rgb(243, 96, 166)");
    });

    it("should have smallest border-radius of all themes", () => {
      getIframeBody()
        .find(".Tab")
        .first()
        .should("have.css", "border-radius", "2px");
    });
  });

  describe("Theme Visual Differentiation", () => {
    it("should render different border-radius for each theme", () => {
      setupAndVisit("brutal");
      getIframeBody()
        .find(".Tab")
        .first()
        .should("have.css", "border-radius", "6px");
    });

    it("should render midnight theme with different styling from default", () => {
      setupMultiTabAndVisit("midnight");
      getIframeBody()
        .find(".Tab")
        .not(".Tab--selected")
        .first()
        .should("have.css", "background-color", "rgb(48, 49, 61)");
    });
  });
});

/**
 * Submit Button State Tests
 * Tests for submit button behavior: disabled during processing,
 * re-enabled after error, loading states, and visual feedback.
 */
import * as testIds from "../../../../src/Utilities/TestUtils.bs";
import {
  getClientURL,
  createPaymentBody,
  changeObjectKeyValue,
} from "../../support/utils";
import { stripeCards } from "../../support/cards";

describe("Submit Button States", () => {
  let publishableKey: string;
  let secretKey: string;
  let getIframeBody: () => Cypress.Chainable<JQuery<HTMLBodyElement>>;
  const iframeSelector =
    "#orca-payment-element-iframeRef-orca-elements-payment-element-payment-element";

  beforeEach(() => {
    publishableKey = Cypress.env("HYPERSWITCH_PUBLISHABLE_KEY");
    secretKey = Cypress.env("HYPERSWITCH_SECRET_KEY");
    getIframeBody = () => cy.paymentElementBody();
    changeObjectKeyValue(
      createPaymentBody,
      "customer_id",
      "submit_button_test_user",
    );
    changeObjectKeyValue(
      createPaymentBody,
      "authentication_type",
      "no_three_ds",
    );
    changeObjectKeyValue(createPaymentBody, "capture_method", "automatic");

    cy.createPaymentIntent(secretKey, createPaymentBody).then(() => {
      cy.getGlobalState("clientSecret").then((clientSecret) => {
        cy.visit(getClientURL(clientSecret, publishableKey));
        cy.waitForSDKReady();
      });
    });
  });

  describe("Initial State", () => {
    it("should render the submit button as visible and enabled on page load", () => {
      cy.get("#submit")
        .should("be.visible")
        .and("not.be.disabled");
    });

    it("should display the submit button with appropriate text", () => {
      cy.get("#submit")
        .should("be.visible")
        .invoke("text")
        .should("not.be.empty");
    });
  });

  describe("Processing State", () => {
    it("should disable submit button immediately after click with valid card", () => {
      const { cardNo, card_exp_month, card_exp_year, cvc } =
        stripeCards.successCard;

      cy.enterCardDetails({ cardNo, card_exp_month, card_exp_year, cvc });

      cy.get("#submit").should("be.visible").click();

      cy.get("#submit").should("be.disabled");
    });

    it("should show loading indicator while payment is processing", () => {
      const { cardNo, card_exp_month, card_exp_year, cvc } =
        stripeCards.successCard;

      cy.enterCardDetails({ cardNo, card_exp_month, card_exp_year, cvc });

      cy.get("#submit").should("be.visible").click();

      cy.get("#submit")
        .should("be.disabled");
    });
  });

  describe("Error Recovery State", () => {
    it("should keep submit button enabled after client-side validation error", () => {
      getIframeBody()
        .find(`[data-testid=${testIds.cardNoInputTestId}]`)
        .safeType("4242 4242");

      getIframeBody()
        .find(`[data-testid=${testIds.expiryInputTestId}]`)
        .safeType("12");

      cy.get("#submit").should("be.visible").click();

      getIframeBody()
        .find(".Error.pt-1", { timeout: 10000 })
        .should("be.visible")
        .and("contain.text", "CVC Number cannot be empty");

      cy.get("#submit")
        .should("be.visible")
        .and("not.be.disabled");
    });

    it("should allow resubmission after fixing validation errors", () => {
      getIframeBody()
        .find(`[data-testid=${testIds.cardNoInputTestId}]`)
        .safeType("4242 4242");

      cy.get("#submit").should("be.visible").click();

      getIframeBody()
        .find(".Error.pt-1", { timeout: 5000 })
        .should("be.visible")
        .and("contain.text", "Card expiry date cannot be empty");

      getIframeBody()
        .find(`[data-testid=${testIds.cardNoInputTestId}]`)
        .clear();

      const { cardNo, card_exp_month, card_exp_year, cvc } =
        stripeCards.successCard;

      cy.enterCardDetails({ cardNo, card_exp_month, card_exp_year, cvc });

      cy.get("#submit").should("be.visible").click();

      cy.contains("Thanks for your order!", { timeout: 10000 }).should(
        "be.visible",
      );
    });
  });

  describe("Submit with Incomplete Fields", () => {
    it("should not process payment when only card number is filled", () => {
      getIframeBody()
        .find(`[data-testid=${testIds.cardNoInputTestId}]`)
        .safeType(stripeCards.successCard.cardNo);

      cy.get("#submit").should("be.visible").click();

      getIframeBody()
        .find(".Error.pt-1", { timeout: 5000 })
        .should("be.visible")
        .and("contain.text", "Card expiry date cannot be empty");

      cy.get("#submit")
        .should("be.visible");
    });

    it("should not process payment when CVC is missing", () => {
      getIframeBody()
        .find(`[data-testid=${testIds.cardNoInputTestId}]`)
        .safeType(stripeCards.successCard.cardNo);

      getIframeBody()
        .find(`[data-testid=${testIds.expiryInputTestId}]`)
        .safeType(
          stripeCards.successCard.card_exp_month +
            stripeCards.successCard.card_exp_year,
        );

      cy.get("#submit").should("be.visible").click();

      getIframeBody()
        .find(".Error.pt-1", { timeout: 5000 })
        .should("be.visible")
        .and("contain.text", "CVC Number cannot be empty");
    });

    it("should not process payment when expiry is missing", () => {
      getIframeBody()
        .find(`[data-testid=${testIds.cardNoInputTestId}]`)
        .safeType(stripeCards.successCard.cardNo);

      getIframeBody()
        .find(`[data-testid=${testIds.cardCVVInputTestId}]`)
        .safeType(stripeCards.successCard.cvc);

      cy.get("#submit").should("be.visible").click();

      getIframeBody()
        .find(".Error.pt-1", { timeout: 5000 })
        .should("be.visible")
        .and("contain.text", "Card expiry date cannot be empty");
    });
  });
});

